// Code node: "Check Sites" (Run Once for All Items)
// Edit this list to monitor your own / client websites.
const SITES = [
  { name: 'n8n (RixGPT)', url: 'https://n8n.rixgpt.com/healthz' },
  { name: 'RixGPT', url: 'https://rixgpt.com' },
  { name: 'GitHub', url: 'https://github.com' },
];
const TIMEOUT_MS = 10000;
const SLOW_MS = 2000;

const results = [];
for (const site of SITES) {
  const started = Date.now();
  let statusCode = 0;
  let error = '';
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: site.url,
      timeout: TIMEOUT_MS,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      json: false,
    });
    statusCode = res.statusCode;
  } catch (e) {
    error = (e && (e.code || e.message)) ? String(e.code || e.message).slice(0, 120) : 'request failed';
  }
  const ms = Date.now() - started;
  const up = statusCode >= 200 && statusCode < 400;
  results.push({
    json: {
      name: site.name,
      url: site.url,
      checkedAt: new Date().toISOString(),
      statusCode,
      ms,
      up,
      state: !up ? 'down' : ms > SLOW_MS ? 'slow' : 'up',
      error,
    },
  });
}
return results;

// Code node: "Record Results" (Run Once for All Items)
// Keeps the last 24h of checks per site (288 x 5-minute checks) in workflow static data.
const KEEP = 288;
const store = $getWorkflowStaticData('global');
store.sites = store.sites || {};
const changes = [];
for (const item of $input.all()) {
  const r = item.json;
  const s = (store.sites[r.url] = store.sites[r.url] || { name: r.name, url: r.url, checks: [], lastState: null, since: r.checkedAt });
  s.name = r.name;
  s.checks.push({ t: r.checkedAt, c: r.statusCode, ms: r.ms, up: r.up });
  if (s.checks.length > KEEP) s.checks = s.checks.slice(-KEEP);
  if (s.lastState !== r.state) {
    if (s.lastState !== null) changes.push({ name: r.name, from: s.lastState, to: r.state, at: r.checkedAt });
    s.lastState = r.state;
    s.since = r.checkedAt;
  }
  s.lastError = r.error || '';
}
store.incidents = [...changes, ...(store.incidents || [])].slice(0, 50);
return [{ json: { checked: $input.all().length, stateChanges: changes } }];

// Code node: "Build Status Page" (Run Once for All Items)
const store = $getWorkflowStaticData('global');
const sites = Object.values(store.sites || {});
const incidents = store.incidents || [];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (iso) => (iso ? new Date(iso).toISOString().slice(0, 16).replace('T', ' ') : '—');
const avg = (a) => (a.length ? Math.round(a.reduce((x, y) => x + y, 0) / a.length) : 0);

const allUp = sites.length && sites.every((s) => s.lastState !== 'down');
const cards = sites
  .map((s) => {
    const checks = s.checks || [];
    const upPct = checks.length ? ((checks.filter((c) => c.up).length / checks.length) * 100).toFixed(2) : '—';
    const last = checks[checks.length - 1] || {};
    const bars = checks
      .slice(-60)
      .map((c) => `<i class="${c.up ? (c.ms > 2000 ? 'slow' : 'up') : 'down'}" title="${esc(fmt(c.t))} · ${c.c || 'ERR'} · ${c.ms} ms"></i>`)
      .join('');
    return `<article class="card">
  <header><span class="dot ${esc(s.lastState)}"></span><h2>${esc(s.name)}</h2><span class="state ${esc(s.lastState)}">${esc(s.lastState || 'pending')}</span></header>
  <div class="muted">${esc(s.url)}</div>
  <div class="bars">${bars || '<span class="muted">Waiting for first check…</span>'}</div>
  <dl><div><dt>Uptime (24h)</dt><dd>${upPct}%</dd></div><div><dt>Avg response</dt><dd>${avg(checks.map((c) => c.ms))} ms</dd></div>
  <div><dt>Last check</dt><dd>${esc(fmt(last.t))} · ${last.c || 'ERR'}</dd></div><div><dt>In this state since</dt><dd>${esc(fmt(s.since))}</dd></div></dl>
  ${s.lastError ? `<div class="err">${esc(s.lastError)}</div>` : ''}
</article>`;
  })
  .join('');

const incidentRows = incidents
  .map((i) => `<li><span class="muted">${esc(fmt(i.at))} UTC</span> — <strong>${esc(i.name)}</strong> changed from ${esc(i.from)} to <span class="state ${esc(i.to)}">${esc(i.to)}</span></li>`)
  .join('');

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="60">
<title>System Status</title>
<style>
:root{--bg:#f6f7f9;--card:#fff;--ink:#16181d;--muted:#6b7280;--line:#e5e7eb;--up:#16a34a;--slow:#d97706;--down:#dc2626}
@media (prefers-color-scheme:dark){:root{--bg:#0f1115;--card:#171a21;--ink:#e8eaed;--muted:#9aa1ad;--line:#2a2f3a}}
*{box-sizing:border-box}body{margin:0;font:14px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink)}
main{max-width:960px;margin:0 auto;padding:24px 16px}h1{font-size:22px;margin:0}
.banner{margin:16px 0;padding:14px 16px;border-radius:10px;color:#fff;font-weight:600;background:${allUp ? 'var(--up)' : 'var(--down)'}}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;margin-bottom:12px}
.card header{display:flex;align-items:center;gap:8px}.card h2{font-size:16px;margin:0;flex:1}
.dot{width:10px;height:10px;border-radius:50%;background:var(--muted)}.dot.up{background:var(--up)}.dot.slow{background:var(--slow)}.dot.down{background:var(--down)}
.state{font-size:12px;font-weight:600;text-transform:uppercase}.state.up{color:var(--up)}.state.slow{color:var(--slow)}.state.down{color:var(--down)}
.bars{display:flex;gap:2px;margin:12px 0;height:28px;align-items:stretch}.bars i{flex:1;border-radius:2px;background:var(--up)}.bars i.slow{background:var(--slow)}.bars i.down{background:var(--down)}
dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px;margin:0}dt{font-size:12px;color:var(--muted)}dd{margin:0;font-weight:600}
.muted{color:var(--muted);font-size:12px}.err{margin-top:8px;color:var(--down);font-size:12px}
ul{padding-left:18px}li{margin:4px 0}
</style></head><body><main>
<h1>System Status</h1><div class="muted">Checked every 5 minutes by n8n · page refreshes every 60s · ${esc(fmt(new Date().toISOString()))} UTC</div>
<div class="banner">${sites.length ? (allUp ? 'All systems operational' : 'Some systems are experiencing issues') : 'Monitoring starts after the first scheduled check'}</div>
${cards}
<h2 style="font-size:16px">Recent incidents</h2>${incidentRows ? `<ul>${incidentRows}</ul>` : '<p class="muted">No state changes recorded.</p>'}
</main></body></html>`;

return [{ json: { html } }];
